import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {
  COMPANY_PACKAGE_REQUEST: 'COMPANY_PACKAGE_REQUEST',
  COMPANY_PACKAGE: 'COMPANY_PACKAGE',
  HEALTH_CARD_STATUS_LIST_REQUEST: 'HEALTH_CARD_STATUS_LIST_REQUEST',
  HEALTH_CARD_STATUS_LIST: 'HEALTH_CARD_STATUS_LIST',
  UPDATE_PAYMENT_STATUS_REQUEST: 'UPDATE_PAYMENT_STATUS_REQUEST',
  UPDATE_PAYMENT_STATUS: 'UPDATE_PAYMENT_STATUS',
  PAID_PARTICIPANT_LIST_REQUEST: 'PAID_PARTICIPANT_LIST_REQUEST',
  PAID_PARTICIPANT_LIST: 'PAID_PARTICIPANT_LIST',
  UNPAID_PARTICIPANT_LIST_REQUEST: 'UNPAID_PARTICIPANT_LIST_REQUEST',
  UNPAID_PARTICIPANT_LIST: 'UNPAID_PARTICIPANT_LIST',
  PENDING_PARTICIPANT_LIST_REQUEST: 'PENDING_PARTICIPANT_LIST_REQUEST',
  PENDING_PARTICIPANT_LIST: 'PENDING_PARTICIPANT_LIST',

  getCompanyPackages: (payload) => (
    {
      type: actions.COMPANY_PACKAGE_REQUEST,
      payload: {
        ...payload,
        method: 'get',
        url: ebUrls.companyPackages
      }
    }
  ),

  getHealthCardStatusList: () => ({
    type: actions.HEALTH_CARD_STATUS_LIST_REQUEST,
    payload: {
      method: 'get',
      url: ebUrls.getHealthCardStatusList
    }
  }),

  updatePaymentStatus: (payload) => ({
    type: actions.UPDATE_PAYMENT_STATUS_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.updateHealthCardStatus
    }
  }),

  getPaidParticipantList: (payload) => (
    {
      type: actions.PAID_PARTICIPANT_LIST_REQUEST,
      payload: {
        ...payload,
        method: 'get',
        url: ebUrls.getPaidParticipantsList
      }
    }
  ),

  getUnpaidParticipantList: (payload) => (
    {
      type: actions.UNPAID_PARTICIPANT_LIST_REQUEST,
      payload: {
        ...payload,
        method: 'get',
        url: ebUrls.getUnpaidParticipantList
      }
    }
  ),
  getPendingParticipantList: (payload) => (
    {
      type: actions.PENDING_PARTICIPANT_LIST_REQUEST,
      payload: {
        ...payload,
        method: 'get',
        url: ebUrls.getPendingParticipantsList
      }
    }
  )
}

export default actions
