import { Button, Upload, Icon, message } from 'antd'
import { useState } from 'react'
import { callWithTimeout } from '../../../../../helpers/utility'
import uploadFile from '../../../../../request/methods/uploadFile'
import ebUrls from '../../../../../request/urls/employeeBenefit'
import { StyledWrapper } from './index.style'

const FileUploadOnGcsAndBackend = ({
  required = false,
  buttonClassName = '',
  buttonType = 'default',
  maxFileAllowed,
  multiple = false,
  minSize = 0.01, // min 10 Kb
  maxSize = 2, // max 2 MB
  identifier,
  initialValue,
  onPreview,
  buttonText = 'Upload',
  accept = '',
  formItemProps = {},
  icon,
  signedUrlEndPoint = ebUrls.generateSignedUrl,
  fileNameLength, // number providing the max length of the string allowed, default will be full
  uploadUrl,
  uploadProps,
  buttonSize = 'default',
  uploadBody
}) => {
  const [loading, setLoading] = useState(false)

  const customRequest = (config) => {
    const { file, onError } = config
    const { size } = file
    const isLtMinSize = size / 1024 / 1024 < minSize
    const isGtMaxSize = size / 1024 / 1024 > maxSize
    if (isLtMinSize) {
      message.error('File is to small, min 10kb')
      callWithTimeout(config.onError)
      return
    }
    if (isGtMaxSize) {
      message.error(`File is to big, max ${maxSize}mb`)
      callWithTimeout(config.onError)
      return
    }
    setLoading(true)
    return uploadFile({
      signedUrl: signedUrlEndPoint,
      body: { file: config.file },
      signedUrlBody: { file_name: encodeURI(file.name), identifier: identifier || 'static_storage', content_type: file.type },
      uploadUrl,
      urlKey: 'url',
      uploadBody
    })
      .then(res => {
        message.success('Upload successfull')
      })
      .catch(err => {
        onError(err)
        const errorMessage = err?.data?.message || 'Upload Failed. Please Try again Later'
        message.error(errorMessage)
      })
      .finally(() => setLoading(false))
  }

  const onChange = (e) => {
  }

  return (
    <Upload
      multiple={multiple === undefined || multiple}
      customRequest={customRequest}
      onChange={onChange}
      fileList={[]}
      {...(onPreview && { onPreview })}
      {...(accept && { accept })}
    >
      <StyledWrapper>
        <Button
          className={buttonClassName}
          type={buttonType}
          size={buttonSize}
          loading={loading}
        >
          <Icon type={icon || 'upload'} /> {buttonText}
        </Button>
      </StyledWrapper>
    </Upload>
  )
}
export default FileUploadOnGcsAndBackend
