/* eslint-disable react-hooks/exhaustive-deps */
import React, { useCallback, useEffect, useState } from 'react'
import { Col, Input, Button, Table, Modal, Typography, Select, notification, Form, Spin, Alert } from 'antd'
import { ColTextAlignRight, RowWithMargin } from '../../../../CommonComponents/index.style'
import { paidColumns, rowSelection } from './constants'
import { useHealthCardStatusList, useUpdatePaymentStatus } from '../../../../state/ParticipantsList/hooks/useParticipantsList'
import PermissionCheckerV2 from '../../../../../../../components/permissionCheckerV2'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'

const { Text } = Typography
const { Option } = Select

const TabPaid = Form.create({ name: 'update-payment-status-form' })(({ form, refreshData, data, metaData, onTableChange, onSearch, location, ...props }) => {
  const [isModalVisible, setIsModalVisible] = useState(false)
  const [selectedRows, setSelectedRows] = useState([])
  const [paymentStatus, setPaymentStatus] = useState('')

  const [{ getHealthCardStatusList, healthCardStatusListData }] = useHealthCardStatusList()
  const [{ updatePaymentStatus }] = useUpdatePaymentStatus()
  const [{ HEALTH_CARD_STATUS_LIST_ERROR, healthCardStatusListStatus, updatePaymentStatusStatus }] = useErrorContextValue()
  const [{ HEALTH_CARD_STATUS_LIST_LOADER, UPDATE_PAYMENT_STATUS_LOADER }] = useLoaderContextValue()
  const { resetError } = useResetError()

  useEffect(() => {
    getHealthCardStatusList()
    return () => {
      resetError(['HEALTH_CARD_STATUS_LIST_ERROR', 'updatePaymentStatusStatus', 'CREATE_PAYMENT_ERROR', 'updatePaymentStatusStatus'])
    }
  }, [])

  useEffect(() => {
    if (updatePaymentStatusStatus === 'success') {
      notification.success({
        message: 'Success',
        description: 'Successfully updated status'
      })
      refreshData()
      resetError(['updatePaymentStatusStatus'])
      setIsModalVisible(false)
    }
  }, [updatePaymentStatusStatus])

  const handleSubmit = useCallback(() => {
    const valuesToBeSend = {}
    if (!paymentStatus) {
      notification.open({
        message: 'Cannot Process',
        description: 'please select status to update'
      })
    }

    const selectedEmployeeIds = selectedRows.filter(item => !item.parent_id).map(item => (item.id))
    valuesToBeSend.employee_ids = selectedEmployeeIds
    const dependentIds = selectedRows.filter(item => !!item.parent_id).map(item => (item.id))
    valuesToBeSend.dependent_ids = dependentIds
    valuesToBeSend.new_status = paymentStatus
    updatePaymentStatus(valuesToBeSend)
  }, [selectedRows, paymentStatus])

  const handleUpdateStatus = useCallback(() => {
    // check if status of selected rows are same or not. if not then show error.
    const statusSet = new Set(selectedRows.map(row => row.health_card_status).filter(status => !!status))
    if (statusSet.size === 0) {
      notification.open({
        message: 'Cannot Process',
        description: 'Please select at least one payment to update status'
      })
      return
    }
    if (statusSet.size > 1) {
      notification.open({
        message: 'Cannot Process',
        description: 'Only select payments with same status'
      })
      return
    }
    setIsModalVisible(true)
  }, [selectedRows])

  const handleSearch = (e) => {
    if (e.target) {
      onSearch(e.target.value, 'PAID')
    }
  }

  return (
    <>
      <Modal
        title='Updating Card Status'
        visible={isModalVisible}
        onOk={handleSubmit}
        onCancel={() => { setIsModalVisible(false) }}
        okText='Submit'
      >

        <Spin spinning={!!(HEALTH_CARD_STATUS_LIST_LOADER || UPDATE_PAYMENT_STATUS_LOADER)}>

          {(HEALTH_CARD_STATUS_LIST_ERROR) && <Alert type='error' message={healthCardStatusListStatus} banner />}
          <RowWithMargin>
            <Col span={12}><Text strong> Total Participant Affected</Text></Col>
            <Col span={12}>{Array.isArray(selectedRows) && selectedRows.length}</Col>
          </RowWithMargin>
          <RowWithMargin>
            <Col span={12}><Text strong>Current Status</Text></Col>
            <Col span={12}>{(Array.isArray(selectedRows) && selectedRows.length && selectedRows[0].health_card_status) || 0}</Col>
          </RowWithMargin>
          <RowWithMargin>
            <Col span={12}><Text strong>New Status</Text></Col>
            <Col span={12}>
              <Select
                style={{ width: '100%' }}
                defaultValue='Status 1'
                value={paymentStatus}
                onChange={(status) => {
                  setPaymentStatus(status)
                }}
              >
                {healthCardStatusListData && healthCardStatusListData.data && selectedRows.length
                  ? healthCardStatusListData.data
                      .slice(healthCardStatusListData.data.indexOf(selectedRows[0].health_card_status) + 1)
                      .map(item => (
                        <Option key={item} vlaue={item}>{item}</Option>
                      )
                      )
                  : null}
              </Select>
            </Col>
          </RowWithMargin>
        </Spin>
      </Modal>
      <RowWithMargin type='flex' justify='end'>
        <Col
          xs={6}
          sm={8}
          md={6}
          span={6}
        >
          <Input
            placeholder='Search participant name'
            onChange={handleSearch}
            value={location.state && location.state.paidSearchText}
            allowClear
          />
        </Col>
        <ColTextAlignRight
          span={8}
          xs={12}
          sm={8}
          md={6}
        >
          <PermissionCheckerV2
            requiredPermission='ops.eb_update_health_card_status'
          >
            <Button
              type='primary'
              onClick={handleUpdateStatus}
            >
              Update Card Status
            </Button>
          </PermissionCheckerV2>
        </ColTextAlignRight>
      </RowWithMargin>
      <Table
        rowSelection={rowSelection(setSelectedRows)}
        columns={paidColumns()}
        dataSource={data}
        onChange={params => onTableChange(params, 'PAID')}
        rowKey={record => record.id}
        pagination={{
          pageSize: metaData.page_size,
          total: metaData.total_records,
          current: metaData.page
        }}
      />
    </>
  )
})

export default TabPaid
