import { format } from 'date-fns'
import { uniq } from 'lodash'

export const unPaidColumns = () => [
  {
    key: 1,
    dataIndex: 'name',
    title: 'Name'
  },
  {
    key: 2,
    title: 'Date of Birth',
    render: (rowData) => format(rowData.dob, 'DD-MM-YYYY')
  },
  {
    key: 3,
    dataIndex: 'gender',
    title: 'Gender'
  },
  {
    key: 4,
    title: 'Relation',
    render: rowData => rowData.parent ? `Dependent of Employee ${rowData.parent.name}` : 'Employee'
  },
  {
    key: 5,
    title: 'Proposed Product Id',
    dataIndex: 'proposed_product_id'
  }
]

export const rowSelection = (setSelectedRows) => ({
  onChange: (selectedRowKeys, selectedRows) => {
    setSelectedRows(selectedRowsPrev => uniq([...selectedRowsPrev.filter(row => selectedRowKeys.includes(row.id)), ...selectedRows], 'id'))
  }
})

