/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState } from 'react'
import { Button, Tabs, Alert, Empty, Spin, Badge, Icon, Row, Col } from 'antd'
import LayoutContentWrapper from '../../../../../../components/utility/layoutWrapper'
import LayoutContent from '../../../../../../components/utility/layoutContent'
import TabPaid from './TabPaid/index'
import TabUnpaid from './TabUnpaid'
import TabPendingPayment from './TabPendingPayment'
import { useResetState } from '../../../state/hooks'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useParticipantList } from '../../../state/ParticipantsList/hooks/useParticipantsList'
import FileUploadOnGcsAndBackend from '../../../components/FileUploadOnGcsAndBackend'
import { ColMrRight } from './index.style'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import ExportExcel from '../../../components/ExportExcel'
import ebUrls from '../../../../../../request/urls/employeeBenefit'

const { TabPane } = Tabs

const ParticipantList = (props) => {
  const { history, location } = props
  const { match } = props
  const { resetState } = useResetState()
  const { resetError } = useResetError()
  const [listData, setlistData] = useState({ unpaid: [], paid: [], pending: [] })
  const [listMetaData, setMetaData] = useState({ unpaid: {}, paid: {}, pending: {} })
  const { activeTab } = location.state || {}

  const [
    {
      paidParticipantListData,
      unpaidParticipantListData,
      pendingParticipantListData
    },
    paidPartPequest,
    unpaidPartPequest,
    pendingPartPequest] = useParticipantList()
  const [
    {
      PAID_PARTICIPANT_LIST_LOADER,
      UNPAID_PARTICIPANT_LIST_LOADER,
      PENDING_PARTICIPANT_LIST_LOADER
    }] = useLoaderContextValue()
  const [
    {
      PAID_PARTICIPANT_LIST_ERROR,
      paidParticipantListStatus,
      UNPAID_PARTICIPANT_LIST_ERROR,
      unpaidParticipantListStatus,
      PENDING_PARTICIPANT_LIST_ERROR,
      pendingParticipantListStatus
    }] = useErrorContextValue()

  const goBack = (params) => {
    history.push(`/employee-benefits/company-list/${match.params.companyId}`)
  }

  const refreshData = () => {
    resetState([
      'paidParticipantListData',
      'unpaidParticipantListData',
      'pendingParticipantListData'
    ])
    resetError([
      'PAID_PARTICIPANT_LIST_ERROR',
      'paidParticipantListStatus',
      'UNPAID_PARTICIPANT_LIST_ERROR',
      'unpaidParticipantListStatus',
      'PENDING_PARTICIPANT_LIST_ERROR',
      'pendingParticipantListStatus'
    ])
  }

  const handleTableChange = (params, type) => {
    const query = {
      page: params.current,
      per_page: params.pageSize,
      company_id: match.params.companyId
    }
    if (type === 'UNPAID') {
      query.search_text = location.state && location.state.unpaidSearchText
      unpaidPartPequest({ query: query })
    }
    if (type === 'PAID') {
      query.search_text = location.state && location.state.paidSearchText
      paidPartPequest({ query })
    }
    if (type === 'PENDING') {
      query.search_text = location.state && location.state.pendingSearchText
      pendingPartPequest({ query })
    }
  }

  useEffect(() => {
    if (PAID_PARTICIPANT_LIST_ERROR === undefined && paidParticipantListStatus === undefined) {
      const query = {
        company_id: match.params.companyId
      }
      query.search_text = location.state && location.state.paidSearchText
      paidPartPequest({ query })
    }
  }, [paidParticipantListStatus])

  useEffect(() => {
    if (UNPAID_PARTICIPANT_LIST_ERROR === undefined && unpaidParticipantListStatus === undefined) {
      const query = {
        company_id: match.params.companyId
      }
      query.search_text = location.state && location.state.unpaidSearchText
      unpaidPartPequest({ query })
    }
  }, [unpaidParticipantListStatus])

  useEffect(() => {
    if (PENDING_PARTICIPANT_LIST_ERROR === undefined && pendingParticipantListStatus === undefined) {
      const query = {
        company_id: match.params.companyId
      }
      query.search_text = location.state && location.state.pendingSearchText
      pendingPartPequest({ query })
    }
  }, [pendingParticipantListStatus])

  useEffect(() => {
    if (unpaidParticipantListData && unpaidParticipantListData.data) {
      setlistData(listData => ({ ...listData, unpaid: unpaidParticipantListData.data }))
      setMetaData(metaData => ({ ...metaData, unpaid: unpaidParticipantListData.meta_data }))
    }
  }, [unpaidParticipantListData])

  useEffect(() => {
    if (paidParticipantListData && paidParticipantListData.data) {
      setlistData(listData => ({ ...listData, paid: paidParticipantListData.data }))
      setMetaData(metaData => ({ ...metaData, paid: paidParticipantListData.meta_data }))
    }
  }, [paidParticipantListData])

  useEffect(() => {
    if (pendingParticipantListData && pendingParticipantListData.data) {
      setlistData(listData => ({ ...listData, pending: pendingParticipantListData.data }))
      setMetaData(metaData => ({ ...metaData, pending: pendingParticipantListData.meta_data }))
    }
  }, [pendingParticipantListData])

  const handleSearch = (searchString, type) => {
    const searchStringLower = String(searchString).toLowerCase()
    const query = {
      search_text: searchStringLower,
      company_id: match.params.companyId
    }
    if (type === 'PAID') {
      paidPartPequest({ query })
      history.push({
        state: {
          ...location.state,
          paidSearchText: searchString
        }
      })
    }
    if (type === 'UNPAID') {
      unpaidPartPequest({ query })
      history.push({
        state: {
          ...location.state,
          unpaidSearchText: searchString
        }
      })
    }
    if (type === 'PENDING') {
      history.push({
        state: {
          ...location.state,
          pendingSearchText: searchString
        }
      })
      pendingPartPequest({ query })
    }
  }

  useEffect(() => {
    return () => {
      resetState([
        'paidParticipantListData',
        'unpaidParticipantListData',
        'pendingParticipantListData'
      ])
      resetError([
        'PAID_PARTICIPANT_LIST_ERROR',
        'paidParticipantListStatus',
        'UNPAID_PARTICIPANT_LIST_ERROR',
        'unpaidParticipantListStatus',
        'PENDING_PARTICIPANT_LIST_ERROR',
        'pendingParticipantListStatus'
      ])
    }
  }, [])

  return (
    <>
      <LayoutContentWrapper>
        <Button type='default' onClick={goBack}><Icon type='caret-left' />Back</Button>
        <LayoutContent>
          <Tabs
            {...(activeTab && { defaultActiveKey: String(activeTab) })}
            tabBarExtraContent={
              <PermissionCheckerV2 requiredPermission='ops.eb_upload_ecard_file'>
                <Row type='flex'>
                  <ColMrRight>
                    <ExportExcel
                      buttonType='link'
                      buttonContent={<><Icon type='cloud-download' /> Sample E-Card Data</>}
                      url={ebUrls.downloadSampleECard}
                    />
                  </ColMrRight>
                  <Col>
                    <FileUploadOnGcsAndBackend
                      buttonType='primary'
                      buttonText='Upload E-Card Data'
                      icon='cloud-upload'
                      identifier='ecard_data'
                      uploadUrl={ebUrls.uploadECard}
                      uploadBody={{ company_id: match.params.companyId }}
                      minSize='0.001'
                    />
                  </Col>
                </Row>
              </PermissionCheckerV2>
            }
          >
            <TabPane tab={<span>Paid</span>} key='1'>
              <Spin spinning={PAID_PARTICIPANT_LIST_LOADER}>
                {PAID_PARTICIPANT_LIST_ERROR && <Alert type='error' message={paidParticipantListStatus} banner />}
                {
                  (paidParticipantListData && !PAID_PARTICIPANT_LIST_ERROR)
                    ? (
                      <TabPaid
                        refreshData={refreshData}
                        data={listData.paid}
                        metaData={listMetaData.paid}
                        onTableChange={handleTableChange}
                        onSearch={handleSearch}
                        location={location}
                      />
                      )
                    : <Empty />
                }
              </Spin>
            </TabPane>
            <TabPane tab={unpaidParticipantListData && unpaidParticipantListData.data ? <>Unpaid<Badge count={listMetaData.unpaid.total_records ? listMetaData.unpaid.total_records : 0} /></> : 'Unpaid'} key='2'>
              <Spin spinning={UNPAID_PARTICIPANT_LIST_LOADER}>
                {UNPAID_PARTICIPANT_LIST_ERROR && <Alert type='error' message={unpaidParticipantListStatus} banner />}
                {
                  (unpaidParticipantListData && !UNPAID_PARTICIPANT_LIST_ERROR)
                    ? (
                      <TabUnpaid
                        refreshData={refreshData}
                        companyId={match.params.companyId}
                        data={listData.unpaid}
                        metaData={listMetaData.unpaid}
                        onTableChange={handleTableChange}
                        onSearch={handleSearch}
                        location={location}
                      />
                      )
                    : <Empty />
                }
              </Spin>
            </TabPane>
            <TabPane tab='Pending payment' key='3'>
              <Spin spinning={PENDING_PARTICIPANT_LIST_LOADER}>
                {PENDING_PARTICIPANT_LIST_ERROR && <Alert type='error' message={pendingParticipantListStatus} banner />}
                <TabPendingPayment
                  data={listData.pending}
                  metaData={listMetaData.pending}
                  onTableChange={handleTableChange}
                  onSearch={handleSearch}
                  location={location}
                />
              </Spin>
            </TabPane>
          </Tabs>
        </LayoutContent>
      </LayoutContentWrapper>
    </>
  )
}

export default ParticipantList
