import { ApiContextProvider } from '@pasarpolis/common-react-hooks'
import React from 'react'
import { EBContextProvider } from '../../context'
import reducer from '../../state/ParticipantsList/reducers'
import ParticipantsListContainer from './containers'

function ParticipantsList (props) {
  return (
    <EBContextProvider reducer={reducer}>
      <ApiContextProvider>
        <ParticipantsListContainer {...props} />
      </ApiContextProvider>
    </EBContextProvider>
  )
}

export default ParticipantsList
