import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useEBContextValue } from '../../../context/index'
import actions from '../actions'

export const useHealthCardStatusList = (payload) => {
  const [{ healthCardStatusListData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const getHealthCardStatusList = (payload) => {
    callApi(actions.getHealthCardStatusList())
  }

  return [{ healthCardStatusListData, getHealthCardStatusList }]
}

export const useUpdatePaymentStatus = (payload) => {
  const [{ updatePaymentStatusData, updatePaymentStatusStatus }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const updatePaymentStatus = (payload) => {
    callApi(actions.updatePaymentStatus({ body: payload }))
  }

  return [{ updatePaymentStatusData, updatePaymentStatusStatus, updatePaymentStatus }]
}

export const useParticipantList = () => {
  const [
    {
      paidParticipantListData,
      paidParticipantListStatus,
      unpaidParticipantListData,
      unpaidParticipantListStatus,
      pendingParticipantListData,
      pendingParticipantListStatus
    }, dispatch] = useEBContextValue()

  const [callApi] = useServiceRequest(dispatch)
  const paidPartPequest = async (payload = {}) => {
    await callApi(actions.getPaidParticipantList(payload))
  }
  const unpaidPartPequest = async (payload = {}) => {
    await callApi(actions.getUnpaidParticipantList(payload))
  }
  const pendingPartPequest = async (payload = {}) => {
    await callApi(actions.getPendingParticipantList(payload))
  }
  return [
    {
      paidParticipantListData,
      paidParticipantListStatus,
      unpaidParticipantListData,
      unpaidParticipantListStatus,
      pendingParticipantListData,
      pendingParticipantListStatus
    },
    paidPartPequest,
    unpaidPartPequest,
    pendingPartPequest]
}

export const useCompanyPackages = () => {
  const [{ companyPackageData, companyPackageStatus }, dispatch] = useEBContextValue()
  //  follow this
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(actions.getCompanyPackages(payload))
  }
  return [{ companyPackageData, companyPackageStatus }, request]
}
