import React, { useCallback, useEffect, useState } from 'react'
import {
  Col,
  Input,
  Table,
  Button,
  Alert,
  Typography,
  Popover,
  Icon,
  notification,
  message,
  Spin
} from 'antd'
import { ColTextAlignRight, RowWithMargin } from '../../../../CommonComponents/index.style'
import { unPaidColumns, rowSelection } from './constants'
import PermissionCheckerV2 from '../../../../../../../components/permissionCheckerV2'
import { useHistory } from 'react-router'
import { useErrorContextValue, useGet, useLoaderContextValue, usePost, useResetError } from '@pasarpolis/common-react-hooks'
import { uniq } from 'lodash'
import { participantListApiConfig } from '../../apiConfig'
import { getSelectedUsersAndDependentsList } from '../../../ParticipantsPayment/containers/utility'

const { Text } = Typography

const TabUnpaid = ({ refreshData, data, metaData, companyId, onTableChange, onSearch, location, ...props }) => {
  const [companyPackageData, getCompanyPackages] = useGet(participantListApiConfig.getCompanyPackages)
  const [proposedPlans, validatePaymentRequest] = usePost(participantListApiConfig.validatePayment)
  const [{ COMPANY_PACKAGE_LOADER, VALIDATE_PAYMENT_LOADER }] = useLoaderContextValue()
  const [{
    COMPANY_PACKAGE_ERROR,
    companyPackageStatus,
    VALIDATE_PAYMENT_ERROR,
    validatePaymentStatus,
    validatePaymentErrorData
  }] = useErrorContextValue()
  const [selectedRows, setSelectedRows] = useState([])
  const { resetError } = useResetError()
  const history = useHistory()

  const getSelectedPackages = useCallback(() => {
    const selectedPackages = []
    for (const { proposed_product_id: proposedProductId } of selectedRows) {
      if (proposedProductId) {
        selectedPackages.push(proposedProductId)
      }
    }
    return selectedPackages
  }, [selectedRows])

  const handleCreate = () => {
    if (selectedRows.length) {
      const selectedPackages = getSelectedPackages()
      if (uniq(selectedPackages).length > 1) {
        notification.error({
          message: 'Cannot proceed with payment',
          description: 'All selected participants should have same product Id'
        })
        return
      }
      const selectedParticipantsWithDependents = getSelectedUsersAndDependentsList(selectedRows)?.map(({ id }) => id)
      validatePaymentRequest({
        company_id: companyId,
        participant_ids: selectedParticipantsWithDependents
      })
    } else {
      history.push({
        pathname: `/employee-benefits/company-list/${companyId}/participants-list/create-payment`
      })
    }
  }

  const isDisabled = () => {
    if (companyPackageData && Array.isArray(companyPackageData.data) && companyPackageData.data.length) {
      return false
    }
    return true
  }

  useEffect(() => {
    if (validatePaymentStatus === 'success') {
      const selectedPackages = getSelectedPackages()
      window.sessionStorage.setItem('selected-employees', JSON.stringify(selectedRows))
      if (selectedPackages?.[0]) {
        window.sessionStorage.setItem('eb-selected-employees-proposed-product-id', selectedPackages?.[0])
      }
      window.sessionStorage.setItem('eb-selected-employees-proposed-plans', JSON.stringify(proposedPlans))
      history.push({
        pathname: `/employee-benefits/company-list/${companyId}/participants-list/create-payment`
      })
    }
  }, [
    proposedPlans,
    validatePaymentStatus,
    selectedRows,
    getSelectedPackages,
    history,
    companyId
  ])

  useEffect(() => {
    if (VALIDATE_PAYMENT_ERROR) {
      const { message: errorMessage } = validatePaymentErrorData || {}
      message.error(errorMessage || validatePaymentStatus)
    }
  }, [validatePaymentErrorData, VALIDATE_PAYMENT_ERROR, validatePaymentStatus])

  useEffect(() => {
    getCompanyPackages({ company_id: companyId })
    return () => {
      resetError([
        'COMPANY_PACKAGE_ERROR',
        'CREATE_PAYMENT_ERROR',
        'validatePaymentStatus',
        'VALIDATE_PAYMENT_ERROR',
        'validatePaymentErrorData'
      ])
    }
  }, [getCompanyPackages, companyId, resetError])

  const handleSearch = (e) => {
    if (e.target) {
      onSearch(e.target.value, 'UNPAID')
    }
  }

  return (
    <Spin spinning={!!VALIDATE_PAYMENT_LOADER}>
      {COMPANY_PACKAGE_ERROR && <Alert type='error' message={companyPackageStatus} banner />}
      <RowWithMargin type='flex' justify='end' gutter={8}>
        <Col
          xs={6}
          sm={8}
          md={6}
          span={6}
        >
          <Input
            placeholder='Search participant list'
            onChange={handleSearch}
            value={location.state && location.state.unpaidSearchText}
            allowClear
          />
        </Col>
        <PermissionCheckerV2 requiredPermission='ops.eb_create_payment'>
          <ColTextAlignRight
            span={8}
            xs={12}
            sm={8}
            md={6}
          >
            <Button
              type='primary'
              onClick={handleCreate}
              loading={!!COMPANY_PACKAGE_LOADER}
              disabled={!COMPANY_PACKAGE_LOADER && isDisabled()}
            >
              Create Payment
            </Button>
          </ColTextAlignRight>
          {isDisabled()
            ? (
              <Col>
                <Popover
                  content={<Text type='danger'>You need to create package, before creating payment</Text>}
                >
                  <Button type='link'>
                    <Icon
                      type='info-circle'
                      theme='twoTone'
                      twoToneColor='#eb2f96'
                    />
                  </Button>
                </Popover>
              </Col>
              )
            : null}
        </PermissionCheckerV2>
      </RowWithMargin>
      <Table
        rowSelection={rowSelection(setSelectedRows)}
        columns={unPaidColumns()}
        dataSource={data}
        rowKey={record => record.id}
        pagination={{
          pageSize: metaData.page_size,
          total: metaData.total_records,
          current: metaData.page
        }}
        onChange={params => onTableChange(params, 'UNPAID')}
      />
    </Spin>
  )
}

export default TabUnpaid
