import React from 'react'
import { Col, Input, Table } from 'antd'
import { RowWithMargin } from '../../../../CommonComponents/index.style'
import { pendingPaymentColumns } from './constants'

const TabPendingPayment = ({ data, metaData, onTableChange, onSearch, location, ...props }) => {
  const handleSearch = (e) => {
    if (e.target) {
      onSearch(e.target.value, 'PENDING')
    }
  }

  return (
    <>
      <RowWithMargin type='flex' justify='end'>
        <Col
          xs={6}
          sm={8}
          md={6}
          span={6}
        >
          <Input
            placeholder='Search participant'
            onChange={handleSearch}
            value={location.state && location.state.pendingSearchText}
            allowClear
          />
        </Col>
      </RowWithMargin>
      <Table
        columns={pendingPaymentColumns()}
        dataSource={data}
        onChange={params => onTableChange(params, 'PENDING')}
        pagination={{
          pageSize: metaData.page_size,
          total: metaData.total_records
        }}
        rowKey={record => record.id}
      />
    </>
  )
}

export default TabPendingPayment
